1	package org.springframework.samples.petclinic.acceptance;
2	
3	import org.junit.jupiter.api.Test;
4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
5	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
6	import tools.jackson.databind.node.ObjectNode;
7	
8	/** telephone-e164: Change how the telephone is handled. Telephone numbers must now be stored in E.164 form: k... */
9	class AcceptanceTest extends AcceptanceBase {
10	
11		@Test
12		void coreNationalToE164() throws Exception {
13			ObjectNode o = ownerNode();
14			o.put("telephone", "0412 345 678");
15			int id = createOwnerOk(o);
16			getOwner(id).andExpect(jsonPath("$.telephone").value("+61412345678"));
17		}
18	
19		@Test
20		void functionalityKeepsExplicitCountryCode() throws Exception {
21			ObjectNode o = ownerNode();
22			o.put("telephone", "+64 21 123 456");
23			int id = createOwnerOk(o);
24			getOwner(id).andExpect(jsonPath("$.telephone").value("+6421123456"));
25		}
26	
27		@Test
28		void errorRejectsUnformattable() throws Exception {
29			ObjectNode o = ownerNode();
30			o.put("telephone", "12");
31			createOwner(o).andExpect(status().isBadRequest());
32		}
33	}
